+export const signSession = (id: string, userId: string, expiresAt: Date): string => {
+  if (!PRIVATE_KEY) {
+    throw new Error(
+      "SESSION_PRIVATE_KEY not configured; session signing unavailable",
+    );
+  }
+
+  const payload = { id, userId, expiresAt: expiresAt.toISOString() };
+  const header = Buffer.from(JSON.stringify({ alg: "RS256", typ: "JWT" })).toString("base64url");
+  const body = Buffer.from(JSON.stringify(payload)).toString("base64url");
+  const message = `${header}.${body}`;
+
+  const signature = sign("sha256", Buffer.from(message), PRIVATE_KEY);
+  const encodedSignature = signature.toString("base64url");
+
+  return `${message}.${encodedSignature}`;
+};
